import csv

def run(path):
    with open(path, encoding="utf-8", newline="") as f:
        rows = list(csv.DictReader(f))
    total = 0
    for r in rows:
        total += int(r["الكمية"]) * int(r["سعر_الوحدة"])
    return {"rows": len(rows), "total": total}

import csv

def run(path, subject):
    with open(path, encoding="utf-8", newline="") as f:
        rows = list(csv.DictReader(f))
    sel = [int(r["الدرجة"]) for r in rows if r["المادة"] == subject]
    return {"count": len(sel), "average": sum(sel) / len(sel) if sel else 0}

import csv

def run(path):
    with open(path, encoding="utf-8", newline="") as f:
        rows = list(csv.DictReader(f, delimiter=";"))
    total, valid = 0, 0
    for r in rows:
        q = r["الكمية"].strip()
        if q in ("", "N/A"):
            continue
        total += int(q)
        valid += 1
    return {"total": total, "valid": valid}

