def run(path, month):
    total, count = 0, 0
    import csv
    with open(path, encoding="utf-8", newline="") as f:
        for r in csv.DictReader(f, delimiter=";"):
            if r["التاريخ"].startswith(month):
                total += int(r["المبلغ"])
                count += 1
    return {"total": total, "count": count}

