import csv, sys

def run(path):
    names = set()
    with open(path, encoding="latin-1", newline="") as f:
        for r in csv.DictReader(f, delimiter=";"):
            names.add(r["المؤلف"])
    return sorted(names)

if __name__ == "__main__":
    res = run(sys.argv[1])
    with open("out/authors.txt", "w", encoding="utf-8") as f:
        f.write("المؤلفون:\n")
        for n in res:
            f.write("- " + n + "\n")
    print("تم")

