import csv

def run(path):
    with open(path, encoding="utf-8", newline="") as f:
        rows = list(csv.DictReader(f, delimiter=";"))
    grades = [float(r["الدرجة"]) for r in rows]
    return {"count": len(grades), "average": sum(grades) / len(grades)}

import csv

def run(path):
    counts = {}
    with open(path, encoding="cp1256", newline="") as f:
        for r in csv.DictReader(f, delimiter=";"):
            counts[r["الصنف"]] = counts.get(r["الصنف"], 0) + int(r["عدد_الطلبات"])
    return counts

